use std::time::{Duration, Instant};

// Game constants
const BOARD_WIDTH: usize = 10;
const BOARD_HEIGHT: usize = 20;
const BLOCK_SIZE: u32 = 30;
const SCREEN_WIDTH: u32 = BOARD_WIDTH as u32 * BLOCK_SIZE;
const SCREEN_HEIGHT: u32 = BOARD_HEIGHT as u32 * BLOCK_SIZE;

// Tetromino shapes (7 standard pieces)
const SHAPES: [[[i32; 2]; 4]; 7] = [
    // I
    [[0, 1], [1, 1], [2, 1], [3, 1]],
    // O
    [[0, 0], [1, 0], [0, 1], [1, 1]],
    // T
    [[1, 0], [0, 1], [1, 1], [2, 1]],
