const COLORS: [Color; 7] = [
    Color::CYAN,    // I
    Color::YELLOW,  // O
    Color::PURPLE,  // T
    Color::GREEN,   // S
    Color::RED,     // Z
    Color::BLUE,    // J
    Color::ORANGE,  // L
];

#[derive(Clone, Copy, PartialEq)]
struct Block {
    x: i32,
    y: i32,
    color: Color,
}

struct Tetromino {
    blocks: [Block; 4],
    shape_index: usize,
}

impl Tetromino {
    fn new(shape_index: usize) -> Self {
        let shape = SHAPES[shape_index];
        let color = COLORS[shape_index];
        let blocks = [
            Block { x: shape[0][0], y: shape[0][1], color },
            Block { x: shape[1][0], y: shape[1][1], color },
            Block { x: shape[2][0], y: shape[2][1], color },
            Block { x: shape[3][0], y: shape[3][1], color },
        ];
        Tetromino { blocks, shape_index }
    }

    fn random() -> Self {
        let mut rng = rand::thread_rng();
        let shape_index = rng.gen_range(0..7);
        Tetromino::new(shape_index)
    }

    fn rotate(&mut self, clockwise: bool) {
        for block in &mut self.blocks {
            let rel_x = block.x - self.blocks[1].x;
            let rel_y = block.y - self.blocks[1].y;
            if clockwise {
                block.x = self.blocks[1].x - rel_y;
                block.y = self.blocks[1].y + rel_x;
            } else {
                block.x = self.blocks[1].x + rel_y;
                block.y = self.blocks[1].y - rel_x;
            }
        }
    }

    fn move_down(&mut self) {
        for block in &mut self.blocks {
            block.y += 1;
        }
    }

    fn move_left(&mut self) {
        for block in &mut self.blocks {
            block.x -= 1;
        }
    }

    fn move_right(&mut self) {
        for block in &mut self.blocks {
            block.x += 1;
        }
    }
}

struct Game {
    board: [[Option<Color>; BOARD_HEIGHT]; BOARD_WIDTH],
    current_piece: Tetromino,
    next_piece: Tetromino,
    score: u32,
    level: u32,
    lines_cleared: u32,
