    fn new() -> Self {
        let board = [[None; BOARD_HEIGHT]; BOARD_WIDTH];
        let current_piece = Tetromino::random();
        let next_piece = Tetromino::random();

        Game {
            board,
            current_piece,
            next_piece,
            score: 0,
            level: 1,
            lines_cleared: 0,
            game_over: false,
            drop_interval: Duration::from_millis(1000),
            last_drop: Instant::now(),
        }
    }

    fn is_valid_position(&self, piece: &Tetromino) -> bool {
        for block in &piece.blocks {
            if block.x < 0 || block.x >= BOARD_WIDTH as i32 {
                return false;
            }
            if block.y >= BOARD_HEIGHT as i32 {
                return false;
            }
            if block.y >= 0 {
                if self.board[block.x as usize][block.y as usize].is_some() {
                    return false;
                }
            }
        }
        true
    }

    fn lock_piece(&mut self) {
        for block in &self.current_piece.blocks {
            if block.y >= 0 && block.y < BOARD_HEIGHT as i32 {
                self.board[block.x as usize][block.y as usize] = Some(block.color);
            }
        }
        self.clear_lines();
        self.current_piece = self.next_piece;
        self.next_piece = Tetromino::random();

        if !self.is_valid_position(&self.current_piece) {
            self.game_over = true;
        }
    }

    fn clear_lines(&mut self) {
        let mut lines_to_clear = Vec::new();

        for y in 0..BOARD_HEIGHT {
            let mut full = true;
            for x in 0..BOARD_WIDTH {
                if self.board[x][y].is_none() {
                    full = false;
                    break;
                }
            }
            if full {
                lines_to_clear.push(y);
            }
        }

        let lines_count = lines_to_clear.len() as u32;
        if lines_count > 0 {
            self.lines_cleared += lines_count;
            self.score += match lines_count {
                1 => 100 * self.level,
                2 => 300 * self.level,
                3 => 500 * self.level,
                4 => 800 * self.level,
                _ => 0,
            };

            // Update level every 10 lines
            self.level = self.lines_cleared / 10 + 1;
            self.drop_interval = Duration::from_millis(1000 - (self.level - 1) * 100);

            // Clear the lines and shift down
            for y in lines_to_clear.iter().rev() {
                for row in (1..=*y).rev() {
                    for x in 0..BOARD_WIDTH {
                        self.board[x][row] = self.board[x][row - 1];
                    }
                }
                for x in 0..BOARD_WIDTH {
                    self.board[x][0] = None;
                }
            }
        }
    }

    fn tick(&mut self) {
        if self.game_over {
            return;
        }

        if Instant::now().duration_since(self.last_drop) >= self.drop_interval {
            let mut moved = self.current_piece.clone();
            moved.move_down();

            if self.is_valid_position(&moved) {
                self.current_piece = moved;
            } else {
                self.lock_piece();
            }
            self.last_drop = Instant::now();
        }
    }

    fn handle_input(&mut self, keycode: Keycode) {
        if self.game_over {
            return;
        }

        match keycode {
            Keycode::Left => {
                let mut moved = self.current_piece.clone();
                moved.move_left();
                if self.is_valid_position(&moved) {
                    self.current_piece = moved;
                }
            }
            Keycode::Right => {
                let mut moved = self.current_piece.clone();
                moved.move_right();
                if self.is_valid_position(&moved) {
                    self.current_piece = moved;
                }
            }
            Keycode::Down => {
                let mut moved = self.current_piece.clone();
                moved.move_down();
                if self.is_valid_position(&moved) {
                    self.current_piece = moved;
                    self.score += 1;
                }
            }
            Keycode::Up => {
                let mut rotated = self.current_piece.clone();
                rotated.rotate(true);
                if self.is_valid_position(&rotated) {
                    self.current_piece = rotated;
                }
            }
            Keycode::Space => {
