                        (x as u32) * BLOCK_SIZE,
                        (y as u32) * BLOCK_SIZE,
                        BLOCK_SIZE - 1,
                        BLOCK_SIZE - 1,
                    );
                    renderer.fill_rect(rect).unwrap();
                }
            }
        }

