        let pivot_x = self.blocks[1].x;
        let pivot_y = self.blocks[1].y;

        for block in &mut self.blocks {
            let rel_x = block.x - pivot_x;
            let rel_y = block.y - pivot_y;
            if clockwise {
                block.x = pivot_x - rel_y;
                block.y = pivot_y + rel_x;
